function spiralOrder(matrix) {
  const result = [];
  let top = 0, bottom = matrix.length - 1;
  let left = 0, right = matrix[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) result.push(matrix[top][c]);   // L -> R
    top++;
    for (let r = top; r <= bottom; r++) result.push(matrix[r][right]); // T -> B
    right--;
    if (top <= bottom) {                                              // guard: row left
      for (let c = right; c >= left; c--) result.push(matrix[bottom][c]); // R -> L
      bottom--;
    }
    if (left <= right) {                                              // guard: col left
      for (let r = bottom; r >= top; r--) result.push(matrix[r][left]);   // B -> T
      left++;
    }
  }
  return result;
}
// Time O(m*n), Space O(1) extra (excluding output)

